} from "./DiscourseRelationTool";
import { TOOL_ARROW_ICON_SVG } from "~/icons";

const TOOL_ARROW_ICON_DATA_URL = `data:image/svg+xml;base64,${btoa(TOOL_ARROW_ICON_SVG)}`;

export const DiscourseToolPanel = ({
  plugin,
  canvasFile,
