    let target: HTMLButtonElement | null = null;

    const handlePointerMove = (e: PointerEvent) => {
      const current = dragState.get();
      const screenPoint = new Vec(e.clientX, e.clientY);
      switch (current.name) {
        case "idle":
          break;
        case "pointing_item": {
