      </div>
    </div>
  );
};

const NodeTypeButton = ({
  nodeType,
  handlers,
  didDragRef,
  onClickNoDrag,
}: NodeTypeButtonProps) => {
  return (
    <button
      key={nodeType.id}
      className="tlui-style-panel__row tlui-button flex h-5 cursor-pointer items-center !justify-start gap-2 px-3"
      data-dg_node_type_id={nodeType.id}
      onPointerDown={handlers.handlePointerDown}
      onPointerUp={handlers.handlePointerUp}
      onClick={() => {
        if (didDragRef.current) return;
        onClickNoDrag();
      }}
    >
      <span
        className="tlui-icon tlui-button__icon mr-2"
        style={{
          mask: `url("https://cdn.tldraw.com/2.3.0/icons/icon/color.svg") center 100% / 100% no-repeat`,
          backgroundColor: nodeType.color || "black",
        }}
      />
      <span className="text-sm">{nodeType.name}</span>
    </button>
  );
};

type NodeTypeSummary = {
  id: string;
  name: string;
  color?: string;
};

type NodeTypeButtonProps = {
  nodeType: NodeTypeSummary;
  handlers: {
    handlePointerDown: (e: React.PointerEvent) => void;
    handlePointerUp: (e: React.PointerEvent) => void;
  };
  didDragRef: React.MutableRefObject<boolean>;
  onClickNoDrag: () => void;
};

const RelationTypeButton = ({
  relationType,
  onClick,
}: {
  relationType: { id: string; label: string; color: string };
  onClick: () => void;
}) => {
  return (
    <button
      key={relationType.id}
      className="tlui-style-panel__row tlui-button flex h-5 cursor-pointer items-center !justify-start gap-2 px-3"
      onClick={onClick}
    >
      <span
        className="tlui-icon tlui-button__icon mr-2"
        style={{
          mask: `url("${TOOL_ARROW_ICON_DATA_URL}") center 100% / 100% no-repeat`,
          backgroundColor: relationType.color || "black",
        }}
      />
      <span className="text-sm">{relationType.label}</span>
    </button>
  );
};

import { App, Modal, Notice, TFile } from "obsidian";
import { createRoot, Root } from "react-dom/client";
import {
  StrictMode,
  useState,
  useEffect,
  useRef,
  useCallback,
  useMemo,
} from "react";
import { DiscourseNode } from "~/types";
import type DiscourseGraphPlugin from "~/index";
import { QueryEngine } from "~/services/QueryEngine";
import { isProvisionalSchema } from "~/utils/typeUtils";
import { getNodeTypeIdForFile } from "~/utils/relationsStore";
import { formatNodeName } from "~/utils/createNode";

// APFS and ext4 both enforce a 255 UTF-8 byte limit per filename component.
const MAX_FILENAME_BYTES = 255;
const MD_EXTENSION_BYTES = 3; // ".md"

const getByteLength = (str: string): number =>
  new TextEncoder().encode(str).byteLength;

// Remove characters from the end until the string fits within maxBytes.
const trimToByteLimit = (str: string, maxBytes: number): string => {
  if (getByteLength(str) <= maxBytes) return str;
  let trimmed = str;
  while (trimmed.length > 0 && getByteLength(trimmed) > maxBytes) {
    trimmed = trimmed.slice(0, -1);
  }
  return trimmed;
};

const computeMaxTitleBytes = (nodeType: DiscourseNode | null): number => {
  const formatOverhead = nodeType
    ? getByteLength(formatNodeName("", nodeType) ?? "")
    : 0;
  return Math.max(1, MAX_FILENAME_BYTES - MD_EXTENSION_BYTES - formatOverhead);
};

type ModifyNodeFormProps = {
  nodeTypes: DiscourseNode[];
  onSubmit: (params: {
    nodeType: DiscourseNode;
    title: string;
    initialFile?: TFile; // for edit mode
    selectedExistingNode?: TFile;
    /** DiscourseRelation.id; when set, relation is created with currentFile as the other end. */
    relationshipId?: string;
    relationshipTargetFile?: TFile;
  }) => Promise<void>;
  onCancel: () => void;
  initialTitle?: string;
  initialNodeType?: DiscourseNode;
  /** Present in edit mode — the file being modified. Also drives `isEditMode`. */
  initialFile?: TFile;
  /** Context file for the "Relationship with …" block (editor "Turn into" flow). */
  currentFile?: TFile;
  /** Hides the search-existing-nodes dropdown. Used when intent is always to create
....
  /** Hides the search-existing-nodes dropdown. Used when intent is always to create
   *  (e.g. file explorer "Convert into"), not to reuse an existing node. */
  disableExistingNodeSearch?: boolean;
  plugin: DiscourseGraphPlugin;
};

export const ModifyNodeForm = ({
  nodeTypes,
  onSubmit,
  onCancel,
  initialTitle = "",
  initialNodeType,
  initialFile,
  currentFile,
  disableExistingNodeSearch = false,
  plugin,
}: ModifyNodeFormProps) => {
  const isEditMode = !!initialFile;
  const [title, setTitle] = useState(initialFile?.basename || initialTitle);
  const [selectedNodeType, setSelectedNodeType] =
    useState<DiscourseNode | null>(initialNodeType || null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedExistingNode, setSelectedExistingNode] =
    useState<TFile | null>(null);
  const [query, setQuery] = useState(initialFile?.basename || initialTitle);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isFocused, setIsFocused] = useState(false);
  const [searchResults, setSearchResults] = useState<TFile[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedRelationshipKey, setSelectedRelationshipKey] = useState<
    string | undefined
  >(undefined);
  const queryEngine = useRef(new QueryEngine(plugin.app));
  const titleInputRef = useRef<HTMLTextAreaElement>(null);
  const popoverRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLUListElement>(null);
  const debounceTimeoutRef = useRef<number | null>(null);
  const selectedFileRef = useRef<TFile | null>(null);

  const maxTitleBytes = useMemo(
    () => computeMaxTitleBytes(selectedNodeType),
    [selectedNodeType],
  );

  // Search for nodes when query changes (only in create mode, and only when search is enabled)
  useEffect(() => {
    if (isEditMode || disableExistingNodeSearch) {
      setSearchResults([]);
      return;
    }
    const searchQuery = query.trim();
    if (searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    if (debounceTimeoutRef.current) {
      window.clearTimeout(debounceTimeoutRef.current);
    }

    setIsSearching(true);
    debounceTimeoutRef.current = window.setTimeout(() => {
      void (() => {
        try {
          const results = selectedNodeType
            ? queryEngine.current.searchDiscourseNodesByTitle(
                searchQuery,
                selectedNodeType.id,
              )
            : queryEngine.current.searchDiscourseNodesByTitle(searchQuery);
          setSearchResults(results);
        } catch (error) {
          console.error("Error searching nodes:", error);
          setSearchResults([]);
        } finally {
          setIsSearching(false);
        }
      })();
    }, 250);
    return () => {
      if (debounceTimeoutRef.current) {
        window.clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, [query, selectedNodeType, isEditMode, disableExistingNodeSearch]);

  const isOpen = useMemo(() => {
    return (
      !disableExistingNodeSearch &&
      !selectedExistingNode &&
      isFocused &&
      searchResults.length > 0 &&
      query.trim().length >= 2
    );
  }, [
    disableExistingNodeSearch,
    selectedExistingNode,
    isFocused,
    searchResults.length,
    query,
  ]);

  useEffect(() => {
    setActiveIndex(0);
  }, [searchResults]);

  useEffect(() => {
    if (isOpen && titleInputRef.current && popoverRef.current) {
      const inputRect = titleInputRef.current.getBoundingClientRect();
      const popover = popoverRef.current;
      popover.style.position = "fixed";
      popover.style.top = `${inputRect.bottom + 4}px`;
      popover.style.left = `${inputRect.left}px`;
      popover.style.width = `${inputRect.width}px`;
    }
  }, [isOpen, query]);

  useEffect(() => {
    if (menuRef.current && isOpen && activeIndex >= 0) {
      const activeElement = menuRef.current.children[
        activeIndex
      ] as HTMLElement;
      if (activeElement) {
        activeElement.scrollIntoView({
          block: "nearest",
          behavior: "smooth",
        });
      }
    }
  }, [activeIndex, isOpen]);

  // Focus the content input on mount so users can start typing immediately,
  // with cursor placed at the end of any pre-filled text
  useEffect(() => {
    const el = titleInputRef.current;
    if (!el) return;
    el.focus();
    const len = el.value.length;
    el.setSelectionRange(len, len);
  }, []);

  useEffect(() => {
    const el = titleInputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }, [query]);

  // Determine available relationships based on current file and selected node type
  const availableRelationships = useMemo(() => {
    if (!currentFile || !selectedNodeType || isEditMode) {
      return [];
    }

    const currentFileCache = plugin.app.metadataCache.getFileCache(currentFile);
    const currentNodeTypeId = currentFileCache?.frontmatter?.nodeTypeId as
      | string
      | undefined;

    if (!currentNodeTypeId) {
      return [];
    }

    // Find all accepted relations that connect the current node type to the selected node type
